from write_dossiers import add
def b(d,e,f=(),s='Partially addressed',k='methodological',c='high'):return dict(description=d,evidence=e,followups=list(f),status=s,kind=k,confidence=c)

add('marval',year=2023,venue='CVPR 2023',title='A New Path: Scaling Vision-and-Language Navigation with Synthetic Instructions and Imitation Learning',pages=[1,3,4,5,6,7,8],
problem='Test whether higher-quality, larger synthetic navigation datasets plus imitation learning can replace complicated RL pipelines. The main challenge is scaling both environments and grounded instructions, while retaining the language style of the evaluation dataset.',
method='§3–4 pp3–6: a randomly initialized mT5-style encoder concatenates instruction, pooled panoramic/action history, current36views and candidates with learned modality/relative-position biases. Fixed640D MURAL-large features inherit large external image–text pretraining. Pretraining combines masked language,20-bin progress classification, candidate-constrained action CE and37-class direction/STOP CE; constrained and unconstrained logits are equally mixed. Fine-tuning updates only word embeddings, using behavioral cloning or one effective DAgger iteration. Experts follow the next reference action when on path, shortest-to-goal when the reference is shortest, and shortest-back-to-reference otherwise. Marky generates3.2M multilingual instructions on491Gibson scenes; graph construction combines learned reachability, geodesic/Euclidean ratio and MST connectivity. SE3DS creates200perturbed panorama variants per Matterport scene. Model pretraining reaches5.14Miterations,batch128 (>650M state examples). Pre-exploration additionally self-trains on evaluation environments and is a separate privileged regime.',
novelty='Large multilingual Marky-Gibson data and a deliberately simple, pure-imitation Transformer demonstrate the importance of instruction quality, environment diversity and distribution correction. It is outside DUET’s dual-branch architecture, although it shares panoramic graph tasks and history pooling.',
results='AUTHOR EXPERIMENT: Table2 p7 replacing low-quality Speaker data with Marky yields large gains; mixing Speaker back in can hurt, so more data is not uniformly better. Table3 RxR test SR60.7/nDTW66.8; pre-exploration61.8/68.6 must be separated. Table4 R2R test62SR/58SPL is not SOTA. Authors attribute weaker R2R transfer to Marky’s RxR language style and acknowledge seen gains exceed unseen gains. VERDICT: strong evidence for data quality/domain matching, but graph F1.70 and synthetic panorama/instruction errors remain. Longer training/model scale vary with datasets in several ablations, so purely causal attribution to one data source is limited.',
implementation='A verified official executable MARVAL repository was not located in the bounded primary-source search. Marky, MURAL, SE3DS and data-generation dependencies are separate artifacts; their existence does not establish full MARVAL reproducibility. The paper provides explicit expert-label rules and objectives.',
bottlenecks=[b('Synthetic-language style can help one benchmark while transferring poorly to another; low-quality additional data may reduce performance.','Tables2–4 and§6',('ScaleVLN','SRDF','NavRAG'),k='data distribution'),b('Automatic graph generation and novel-view rendering add synthetic transition/observation errors; larger dataset claims also consume substantial compute.','§4 graphF1=.70;5.14Miterations',('ScaleVLN graph refinement',),k='data/compute')],followups=['https://github.com/wz0919/ScaleVLN','https://github.com/MrZihan/NavRAG'])

add('navillm',year=2024,venue='CVPR 2024',pages=[1,3,4,5,6,7],
problem='Unify instruction navigation, object localization, trajectory summarization,3DQA and held-out EQA within a multimodal language model. Multi-task transfer is central; a model trained on several embodied datasets is distinct from an untouched general VLM used zero-shot.',
method='Paper §3–4 pp3–5: frozen EVA-CLIP-Large428M gives per-view CLS features; a2-layer1024D Transformer fuses views plus angle/GPS information; projections align them to Vicuna-7B. Prompts contain Task, indexed Observation, indexed History and Output Hint. Paper describes generation of view/object IDs, summaries or answers using unified token CE, L=−Σj log pθ(yj|prompt,y<j). History stores selected-view representations. Pretraining10ksteps and multi-task fine-tuning5k,batch64,Adam3e−5,8A100≈80h; teacher/student forcing alternate. Data includesCVDN,SOON,R2R,REVERIE,ScanQA,augmentation andLLaVA23k. Test uses greedy generation except temperature.01 forSOON/REVERIE. RELEASED-CODE QUALIFICATION: nav_model.py additionally uses global graph candidate embeddings and visited masks, merges local embeddings, permutes candidates, then applies a classifier head to LLM CLS hidden states for navigation logits. Thus the release contains DUET-derived graph infrastructure and the action path is not simply unrestricted textual ID generation.',
novelty='Schema-unified embodied multi-task adaptation of an LLM, with transfer to held-out tasks. The contribution is broader than a stronger R2R policy. Paper-versus-release differences should be resolved before using it as a supposedly graph-free VLM baseline.',
results='AUTHOR EXPERIMENT: Table1 p6 CVDN test7.90 is goal progress in meters, despite its caption incorrectly saying SPL forCVDN; SOON26.26SPL,R2R60SPL,REVERIE32.33SPL. Table2 ScanQA test exact-match26.3. Table4 p7 held-outEQA navigation47.78SR/35.60SPL,answer44.5%; EQA dataset was manually filtered for invalid endpoints (§4.4), so release/filter matching matters. Held-out task comparisons support transfer, while random-LLM initialization and multi-task ablations show dependence on language pretraining/data. VERDICT: useful generalist baseline, not universal dominance over specialized models.',
implementation='Inspected scene encoder, global/local navigation embeddings, prompt construction interface, classifier output, task agents and loss-return paths. The release reuses graph structures beyond the simplified paper diagram. No checkpoint/runtime validation was performed.',
code=[dict(path='models/nav_model.py',locator='forward_navigation129–247',finding='Builds global graph embeddings, masks visited nodes, merges local views, permutes candidates, applies out_head to LLM CLS states and returns fused logits.'),dict(path='models/nav_model.py',locator='summarization251–344;object grounding407 onward',finding='Other tasks route through language-model losses/heads; training objectives depend on task mode.'),dict(path='models/image_embedding.py',locator='multi-view embedding classes',finding='Encodes visual and geometric inputs before the language model.'),dict(path='tasks/agents/mp3d_agent.py',locator='rollout/teacher-action paths',finding='Graph navigation and supervision sit outside the LLM module.')],
bottlenecks=[b('Shared multi-task training does not eliminate action grounding failures; broad transfer and specialized endpoint accuracy trade off.','Tables1,3,4',('RoomTour3D action-enriched data','GA-VLN geometry tokens')),b('Released action implementation differs from the paper’s generative description; matching architecture/checkpoint/protocol is a reproducibility prerequisite.','Pinned nav_model.py129–247',(),s='Uncertain because evidence is insufficient',k='implementation')],followups=['https://roomtour3d.github.io','https://github.com/jahhaoyang/GA-VLN'])

add('navrag',year=2025,venue='ACL 2025',pages=[1,3,4,5,6,7,8,9],
problem='Generate diverse user-demand-oriented goal instructions beyond the narrow style of trajectory speakers trained on smallR2R/REVERIE corpora. NavRAG is primarily a data-generation system; its downstream DUET does not perform LLM retrieval at navigation time.',
method='§3 pp3–5 builds a bottom-up scene description tree from object/view to viewpoint, semantic-connectivity zone, and house. GPT-4o-mini describes6views per viewpoint; zones grow by connectivity plus LLM semantic membership, rather than Euclidean clustering alone. Scene context and20manually specified user profiles generate rough daily tasks, then top-down zone→viewpoint→view retrieval refines the instruction and selects a target. A graph planner supplies the path. Training data has2,115,019instructions across861training scenes (800HM3D+61MP3D); separate11MP3D validation scenes are annotated for evaluation. Graph generation follows ScaleVLN. The trained navigation model uses DUET imitation/pretraining machinery, with object-box features removed in fairer downstream comparisons. No new inference loss is introduced by the data pipeline; instruction quality rests on a chain of model-generated descriptions/targets.',
novelty='User-demand simulation and hierarchical retrieval grounded in scene connectivity expand language diversity relative to route-to-text speakers. This does not certify factual correctness: the authors’ Limitations explicitly state no effective correctness evaluator and viewpoint-level, not precise object-level, target annotations.',
results='AUTHOR EXPERIMENT: Table2p7 DUET trained onNavRAG achievesNavRAG30.7SR/25.4SPL versusScaleVLN-REVERIE17.4/11.9; transfer toREVERIE36.1/24.9 is a distinct setting. Table3p8 matched no-object-box fine-tuning yields57.3SR/42.0SPL versusScaleVLN55.9/40.6. Table4 generator ablations change both training and validation generation processes (GraphRAG→GraphRAG versusNavRAG→NavRAG), so navigation differences do not isolate annotation correctness under a fixed test distribution. VERDICT: useful diversity/transfer evidence with explicitly unresolved semantic validation; prose task requests to manipulate objects are evaluated only as navigation.',
implementation='Inspected downstream DUET agent/environment/pretraining, conversion script, evaluator helper and training config. Full scene annotation/generation service reproducibility depends on released prompts, API behavior and data; no API generation was executed.',
code=[dict(path='VLN-DUET-NAVRAG/map_nav_src/NavRAG/agent.py',locator='teacher/rollout/navigation routines',finding='Downstream policy is a DUET-family graph navigator.'),dict(path='VLN-DUET-NAVRAG/pretrain_src/train_rag.py',locator='training loop and data configuration',finding='Dataset pretraining is a distinct optimization stage.'),dict(path='instruction_generator/convert_to_dataset.py',locator='instruction/path conversion',finding='Generated annotations are converted into navigation training records.'),dict(path='VLN-DUET-NAVRAG/map_nav_src/scripts/rag_h14_envedit_mix.sh',locator='experiment configuration',finding='Feature/data mixture choices are explicit and must be controlled.')],
bottlenecks=[b('Generated descriptions, retrieval and target selection share model biases; navigation success on generated targets does not independently establish instruction truth.','§6Limitations;Table4 varying train/testgeneration',('SRDF consistency filtering','CAST counterfactual audit'),s='Still unresolved in the reviewed literature',k='data verification'),b('Targets are viewpoint-level and cannot support precise object manipulation claims.','§6Limitations',('REVERIE object grounding',),k='annotation granularity')],followups=['https://arxiv.org/abs/2508.13446','https://github.com/wz0919/VLN-SRDF'])

add('roomtour3d',year=2025,venue='CVPR 2025',pages=[1,3,4,5,6,7,8],
problem='Extract useful indoor navigation supervision from real room-tour videos, avoiding the lack of measured motion in unordered rental images and the limited scene diversity of simulator annotations. Video motion still does not automatically provide valid alternative robot actions.',
method='§3 pp3–5: sample video frames every2seconds; BLIP-2 predicts16room types with temporal smoothing; RAM tags objects,GroundingDINO boxes them,DepthAnything estimates depth. Text templates combine object category,relative direction/distance and room labels;GPT-4-Turbo turns frame sequences into trajectory descriptions. COLMAP reconstructs clips sampled3fps,100seconds with10second overlaps, merging reconstructions sharing>3frames. Turning/revisited-location candidates are selected using orientation/cosine changes,NMS andDBSCAN; actual continuation is positive and strongly different orientations supply negatives. Dataset totals200k instructions,17kaction-enriched trajectories,1847scenes. NaviLLM first learns trajectory summarization with token CE, then candidate-action prediction using action-enriched histories; human/simulator multi-task data remains in the regular supervised setting. Zero-shot-transfer variant removes simulator action/geometric training but still learns from RoomTour3D actions.',
novelty='Real-video object/motion/geometry annotation and action-candidate mining, rather than a new backbone. Compared withAirBERT, ordered video and reconstructed geometry provide stronger motion evidence; reconstructed candidate views still differ from online reachable-neighbor observations.',
results='AUTHOR EXPERIMENT: Table1p7 reproducedNaviLLM R2RvalSPL56.7→62.4,REVERIE31.4→37.4 withactiondata. Compare against reproduced baseline, not only original published59/35.7. CVDN test GP7.90original versus7.22actiondata is not a universal gain. Zero-shot-transferR2R14.33SR/10.86SPL is far below GPT-4VMapGPT43.7/34.8, though above certain open7Bbaselines. §5.4p8 human audit100descriptions:mean3.08/4,74%mostly/perfectly relevant;26%fall below that bar. VERDICT: useful scalable supervision with measurable residual noise, not verified perfect trajectories.',
implementation='Official NaviLLM fork pinned. Retrieved task agent,video dataset/environment,model,train driver andmulti-task config. Geometry/data-curation release completeness is audited separately from training code availability.',
bottlenecks=[b('Video reconstruction and generated semantic labels can be wrong; sparse human audit establishes useful relevance, not exact action/landmark truth.','§3COLMAP/experts;§5.4humanratings',('SRDF-style consistency audits','counterfactual data validation'),k='data quality'),b('Video-derived candidate frames may contain future-position visual information unlike real current-view candidates; training/deployment observation matching must be controlled.','§3.2/§4.3candidate construction',(),s='Uncertain because evidence is insufficient',k='data/protocol')],followups=['https://github.com/roomtour3d/roomtour3d-NaviLLM'])

add('topologicalplanning',year=2021,venue='CVPR 2021',title='Topological Planning with Transformers for Vision-and-Language Navigation',pages=[1,3,4,5,6,7],
problem='Separate semantic global planning from low-level control using an agent-constructed topological map. The setup explicitly pre-explores each environment with10trajectories before instruction execution, usesRGB-D panoramas/heading and ground-truth odometry for map construction, then learned localization during navigation.',
method='§3pp3–6: sparsify/merge exploration graphs using reachability estimation; nodes store globally oriented panoramas and edges quantized8directions×3distancebins. A message-passing GNN encodes node/edge/global context, followed by map/text/cross-modalTransformer layers. It autoregressively selects a node sequence y with p(y|G,L)=Πtp(yt|y<t,G,L); learned trajectory-position embeddings mark selected and unselected nodes. Node+STOPclassification usesCE/AdamW. A separatelyDAgger-trained controller receives previous/current/subgoalpanoramas and predicts24sectorheading anddistance. A Gaussian stubbornness bias favors the previous direction to suppress perceptual-aliasing oscillations. Low-level actions rotate15degrees or move.25m; predicted distance triggers advancement to the next planned node. The plan is computed before execution, distinct from online map exploration.',
novelty='Learned cross-modal global plan on an automatically built topology plus modular learned visual localization/control. Crucial stopping prior art: §4.1p6 explicitly compares categoricalSTOP, separate binaryCE STOP jointly trained withnodeCE(CMTP-BCE), repeated-node stopping, and noSTOP. A2027 proposal cannot claim that binary stop supervision alone is new.',
results='AUTHOR EXPERIMENT: Table1p6 unseenAGmap categoricalSR26.0 versusBCE27.3;R2Rgraph28.7versus30.2. NoSTOP oracle success64.0/60.5 after20planningsteps highlights opportunity but adds exploration and does not isolate softmax as the cause. Table2p7 controller results show large benefit from direction hysteresis; e.g.AG unseen82.5→89.6 withσ²3. VERDICT: systematic planner/controller/stopping ablations, with pre-exploration and sensor assumptions that preclude direct comparison to unknown-scene single-runDUET.',
implementation='Official project https://topovln.stanford.edu/ exposes map assets and a Code mailto contact rather than a public repository link. No email was sent. No executable source or commit was inspected; availability is a bounded search limitation, not a claim that implementation does not exist.',
bottlenecks=[b('Stopping and map-quality errors persist even when topology is pre-explored; separateBCE helps modestly but does not close the noSTOPoraclegap.','Table1p6',('DUET learned online topology','HSGM doubleconfirmation')),b('Pre-exploration, true mapping odometry and staticplan assumptions shift cost and uncertainty outside instruction-time planning.','§3/§4',('CM² online map prediction','IVLN opportunistic persistentmemory'),k='protocol/resource')],followups=['https://topovln.stanford.edu/','https://github.com/cshizhe/VLN-DUET'])

add('reverie',year=2020,venue='CVPR 2020',pages=[1,3,4,5,6,7,8],
problem='REVERIE requires navigating to and identifying a remote object described by a high-level command, rather than merely stopping near a location. Object recognition and stopping are coupled; correct navigation alone is insufficient.',
method='§3pp4–5:21,702instructions over4,140targetobjects in489categories; target boxes are projected from3Dobject annotations into simulatorviews and retained within3m. The agent receives panoramicRGB andnavigableviewpoints and may output one targetbox/ID; candidate-box selection orIoU≥.5 counts correct. Multiple valid viewpoints can see the object. The baseline combinesFAST-short navigation withMAttNet subject/location/relation matching. For eachview, top3matchingobjects provide averagedvisual features andBiLSTM-encodedcategorylabels concatenated withpanoramicfeatures. Navigation usesactionCE+progressMSE;pointerusesmarginranking L=Σ[δ+S(o,r−)−S(o,r)]+ +[δ+S(o−,r)−S(o,r)]+. PaperEq8prints a negative squared-error term and refers tologits as probabilities; released loss implementation must be used to disambiguate rather than minimizing the literal expression. Pointer is trained then supplies objectinformation fornavigator (§5.1), qualifying the compact jointlossdescription.',
novelty='Remote referring-expression benchmark with jointnavigation/grounding and an interactive navigator–pointer baseline. It tests objectidentity beyondgoalproximity but often supplies annotatedobjectboxes, which are privileged perception proposals relative to real deployment.',
results='AUTHOR EXPERIMENT:Table3p8 baselinejointtestREVERIEsuccess11.28 versusFAST+pointer7.07 andhuman77.84;navigationSR19.88. Table4 attruegoalMAttNet48.98 versushuman90.76 shows grounding itself remains difficult. The language-only baseline is weak, but this does not establish that every trainedmodeluses all semanticrelations. VERDICT: must reportRGS/RGSPL alongsideSR/SPL and distinguishGTboxesfromdetectedboxes; goal-onlydatasetscannot replace this evaluation.',
implementation='Pinned official release includesnavigationmodel/trainer andeval_release.py; modelFast.py andfollower.py were retrieved to checkloss/stopping/groundingpaths. Dataset/simulatoraccess remains required forreproduction.',
bottlenecks=[b('Navigation success can hideincorrectobjectidentity; annotation-providedproposals simplify perception.','§3metrics;Table4goal-onlygrounding',('DUETobjectbranch','GaussianMap','NavRAGno-boxnavigation'),k='evaluation/perception'),b('Goal-directedinstructions mayomitneededrouteevidence andmultipleobjects/viewscreateambiguity; endpointconfidence is notobjectconfidence.','Datasetdefinitionandpointererrors',('KERMknowledge','NaviLLMmultitaskgrounding'))],followups=['https://github.com/cshizhe/VLN-DUET','https://github.com/LaVi-Lab/NaviLLM'])

add('rxr',year=2020,venue='EMNLP 2020',pages=[1,3,4,5,6,7,8],
problem='ReduceR2Rshortest-path/lengthbias andprovide multilingualdense grounding. RxRcontains126,069spoken/transcribedinstructions inEnglish,Hindi,Telugu over16,522paths, plusguide/followerpose traces. It directly targetsagents thatreachgoalswhileignoringrouteconstraints.',
method='§3–4pp3–6 samples a simple roomsequence then a shortestpanoramapath constrainedtothatsequence; greedyselection favorscoverage andnon-shortestglobalroutes.44.5%paths are not globallyshortest; average14.9m,27.4%longer thanshortest. Spokeninstructiontimestamps align viaASR/transcriptDTW to6DOFposes; humanfollowersvalidateinstructions andsupply alternativepaths. PrimarymetricsnDTW/sDTW measurepathadherence, since endpointSRaloneis insufficient. Baseline§5p7usesmultilingualBERTwordfeatures,CNNtextencoder,LSTMpolicy andEfficientNet-B4imagefeatures. Train50%behavior-cloning and50%policy-gradientrollouts withincrementalnDTWreward. Groundingauxiliaryloss L(z,m)=logΣiexpzi−logΣimiexpzi=−log(attentionmassonobservedfeatures), wherebinarym labels viewedregions; analogouswordmask.100ksteps,batch32,Adam1e−4. Inferenceusesfullinstruction/panorama; humantracesaresupervision,notinput.',
novelty='Multilingualspokeninstructions,denseposealignment,highvariance/non-shortestpaths,andhumanalternativepaths. Thedatasetoffersdirectsupervisionforlanguageprogress,butthepaper’s own attention-supervisionresults aremixed,so annotationavailabilitydoesnotautomaticallymean solvedgrounding.',
results='AUTHOR EXPERIMENT:Table4p6 correct-first-step-then-straightSR27.2onR2Rversus13.7onRxR,confirmingreducedshortcutbias. Table5p8guide+followertrainingimprovesmonolingualSR;multilingualjointtrainingandautomatictranslationcanhurt. Visualattentionsupervisionhasmixedmetrics; textualattentionmaskingdidnotimproveperformance. Table6simplecrossdatasettransferisweakdespitesharedbuildings. VERDICT: mandatorycontrolforroutefaithfulnessproposals; reportlanguage/guide-followertrainingconditions and avoid treating allEnglishsubsets aswholeRxR.',
implementation='Officialdatarepositorypinned; inspectedreleaseREADME/dataformat andavailableassets. Baselineis implementedinVALANperpaper; availabilityofdatarepo doesnotconstituteinspectionofVALANmodelcode. Datasetalignmentandmetricdetailsareprimaryevidence.',
bottlenecks=[b('Densehumanalignmentisnoisy/partial andsimpleattentionconstraintsdonotconsistentlyimprovepolicyperformance.','§5groundingsupervision/Table5',('GELA languagealignment','MARVAL','SkillNav'),k='supervision'),b('Multilingualandcrossdatasetdistributiondifferencespersistdespitemoredata/sharedscenes.','Tables5–6',('MARVALmultilingualMarkydata','NavRAGdiversification'),k='generalization')],followups=['https://github.com/google-research-datasets/RxR','https://github.com/google-research/valan'])
